from __future__ import annotations

import ctypes
import json
import os
import warnings

from .._telemetry import track as _track
from . import runtime
from .runtime import synchronized
from .tools import build_schema, pydantic_schema, _is_pydantic_model
from .grounding import (
    _jsonable, _source_years,
    _with_date_fact, _annotate_ungrounded, _validate_extraction,
    _ungrounded_paths, _grounded_number_paths,
)

UNRESET_TURNS = 4


_CACT_GENERATIONS = {
    0x05E12A83: 2,
    0x05E12A84: 3,
}


def _weight_generation(path):
    with open(path, "rb") as handle:
        tag_bytes = handle.read(4)
    if len(tag_bytes) != 4:
        raise RuntimeError(f"{path} is not a complete .cact archive")
    tag = int.from_bytes(tag_bytes, "little")
    try:
        return _CACT_GENERATIONS[tag]
    except KeyError as exc:
        raise RuntimeError(
            f"{path} has unknown .cact format tag 0x{tag:08x}; "
            "cannot choose a compatible Needle engine") from exc


_CACT_HEADER = "<48If"
_CACT_RECORD = "<BBHIIIIQQII"
_CACT_FP16, _CACT_RAW = 1, 4
_CONFIDENCE_HEAD_CODE = 2


def _confidence_head_present(path):
    """Whether a Needle 3 archive carries a confidence head, read from its head manifest."""
    import struct

    with open(path, "rb") as handle:
        header = handle.read(struct.calcsize(_CACT_HEADER))
        if len(header) < struct.calcsize(_CACT_HEADER):
            return False
        fields = struct.unpack(_CACT_HEADER, header)
        num_tensors, codebook = fields[1], fields[2]
        handle.seek(codebook * 4, 1)
        size = struct.calcsize(_CACT_RECORD)
        records = [struct.unpack(_CACT_RECORD, handle.read(size)) for _ in range(num_tensors)]
        if not records or records[-1][0] != _CACT_RAW:
            return False
        for heads in (1, 2, 3):
            index = num_tensors - 2 - 6 * heads
            if index < 0:
                continue
            dtype, ndim, _, length = records[index][:4]
            if dtype != _CACT_FP16 or ndim != 1 or length != heads:
                continue
            handle.seek(records[index][7])
            codes = struct.unpack(f"<{heads}e", handle.read(2 * heads))
            return _CONFIDENCE_HEAD_CODE in {int(round(c)) for c in codes}
    return False


class Cactus:
    def __init__(self, tools=None, system=None, weights=None, tool_index_path=None, buffer_size=65536,
                 auto_date=True, generation=None, stateless=False):
        self._functions = {}
        self._stateless = bool(stateless)
        self._turns = 0
        self._weights = os.fspath(weights) if weights is not None else None
        self._tuned = self._weights is not None
        if self._tuned:
            self._generation = _weight_generation(self._weights)
        else:
            self._generation = int(generation or 3)
        from . import fetch
        fetch._engine(self._generation)
        self._worker = None
        self._closed = False
        self._calibrated = (not self._tuned
                            or (self._generation >= 3 and _confidence_head_present(self._weights)))
        if not self._calibrated:
            warnings.warn("these weights carry no confidence head trained for them, so this "
                          "agent reports confidence as None; platform fine-tunes keep the head",
                          stacklevel=2)
        self._system_text = _with_date_fact(system or "") if auto_date else (system or "")
        self._system = self._system_text.encode("utf-8")
        tools_json = tools if isinstance(tools, str) else json.dumps(self._resolve(tools))
        self._tools_json = tools_json.encode("utf-8")
        try:
            parsed_tools = json.loads(tools_json)
            self._n_tools = len(parsed_tools)
        except (json.JSONDecodeError, TypeError):
            parsed_tools, self._n_tools = [], None
        self._tool_schemas = [entry for entry in (parsed_tools or [])
                              if isinstance(entry, dict)]
        self._seen_years = set()
        self._tool_index_path = (os.fspath(tool_index_path).encode("utf-8")
                                 if tool_index_path else None)
        self._buffer = ctypes.create_string_buffer(buffer_size)
        if self._weights:
            from .._worker import FineTuneWorker
            self._worker = FineTuneWorker(
                runtime._library_path(self._generation), self._weights,
                self._system.decode("utf-8"), self._tools_json.decode("utf-8"),
                os.fspath(tool_index_path) if tool_index_path else None,
                buffer_size)
        else:
            self._bind()

    @synchronized
    def _bind(self):
        if self._closed:
            raise RuntimeError("Cactus instance is closed")
        if self._worker is not None:
            return
        generation = self._generation
        lib = runtime._lib(generation)
        runtime._load_base(lib, generation)
        if runtime._active.get(generation) is self:
            return
        if lib.cactus_init(self._system, self._tools_json, self._tool_index_path) < 0:
            runtime._active.pop(generation, None)
            raise RuntimeError("cactus_init failed")
        runtime._active[generation] = self
        self._seen_years = set()

    def _resolve(self, tools):
        schemas = []
        for entry in tools or []:
            if _is_pydantic_model(entry):
                schema = pydantic_schema(entry)
                self._functions[schema["name"]] = entry
                schemas.append(schema)
            elif callable(entry):
                schema = getattr(entry, "_cactus_tool", None) or build_schema(entry)
                self._functions[schema["name"]] = entry
                schemas.append(schema)
            elif isinstance(entry, dict):
                schemas.append(entry)
        return schemas

    def _track_props(self):
        return {"n_tools": self._n_tools, "tuned": self._tuned,
                "generation": self._generation}

    @synchronized
    def complete(self, text: str = "", max_new_tokens: int = 512, *, audio=None, language=None,
                 keywords=None, word_timestamps=False) -> dict:
        _track("complete", self._track_props())
        if self._stateless:
            self.reset()
        if audio is not None and text:
            raise ValueError("complete accepts either text or audio")
        self._count_query()
        if audio is not None:
            return self._complete_audio(audio, max_new_tokens, language, keywords, word_timestamps)
        return self._complete(text, max_new_tokens)

    def _count_query(self):
        self._turns += 1
        if self._turns == UNRESET_TURNS + 1:
            warnings.warn(
                f"{UNRESET_TURNS} queries on this agent without reset(): every turn stays in "
                "the conversation, so unrelated queries lose accuracy and confidence. "
                "Call reset() between independent queries, or construct with stateless=True",
                stacklevel=3)

    @synchronized
    def _complete(self, text: str, max_new_tokens: int = 512,
                  ground: bool = True) -> dict:
        self._bind()
        self._seen_years |= _source_years(text or "")
        if self._worker is not None:
            raw = self._worker.complete(text, max_new_tokens)
        else:
            lib = runtime._lib(self._generation)
            audio = (None, 0)
            rc = lib.cactus_complete(
                text.encode("utf-8"), *audio, int(max_new_tokens), self._buffer,
                len(self._buffer))
            if rc < 0:
                detail = self._buffer.value.decode("utf-8", "replace")
                raise RuntimeError(detail or f"cactus_complete failed (code {rc})")
            raw = self._buffer.value.decode("utf-8")
        return self._response(raw, text, ground)

    def _complete_audio(self, audio, max_new_tokens, language, keywords, word_timestamps):
        from .audio import _samples, _options
        from .whistle import Whistle, _weights_path
        self._bind()
        samples, count = _samples(audio)
        if keywords is not None and not isinstance(keywords, str):
            keywords = "\n".join(keywords)
        if self._worker is not None:
            packed = ctypes.string_at(samples, count * ctypes.sizeof(ctypes.c_float))
            raw = self._worker.complete_audio(packed, _weights_path(), language, keywords, word_timestamps, max_new_tokens)
        else:
            speech = Whistle()
            lib = speech._bind()
            language, keywords = _options(language, keywords)
            lib.cactus_set_audio(language, keywords, int(bool(word_timestamps)))
            code = lib.cactus_complete(None, samples, count, int(max_new_tokens), self._buffer, len(self._buffer))
            if code < 0:
                raise RuntimeError(lib.cactus_last_error().decode("utf-8", "replace"))
            raw = self._buffer.value.decode("utf-8")
        response = json.loads(raw)
        heard = response.get("audio_text", "")
        self._seen_years |= _source_years(heard)
        return self._response(raw, heard)

    def _response(self, raw, text, ground=True):
        try:
            response = json.loads(raw)
        except json.JSONDecodeError as err:
            raise RuntimeError(
                f"engine returned an unparseable envelope ({err}); this is an "
                f"engine bug - please report it with the prompt and schema") from err
        if not self._calibrated:
            response["confidence"] = None
        if ground:
            _annotate_ungrounded(response, self._tool_schemas, self._seen_years,
                                 self._system_text, text)
        return response

    @synchronized
    def embed(self, text: str = "") -> list[float]:
        self._bind()
        if self._worker is not None:
            return self._worker.embed(text)
        lib = runtime._lib(self._generation)
        dim = lib.cactus_embed(text.encode("utf-8"), None, 0, None, 0)
        if dim <= 0:
            raise RuntimeError(f"cactus_embed failed (code {dim})")
        output = (ctypes.c_float * dim)()
        rc = lib.cactus_embed(text.encode("utf-8"), None, 0, output, dim)
        if rc != dim:
            raise RuntimeError(f"cactus_embed failed (code {rc})")
        return list(output)

    def run(self, query: str = "", max_steps: int = 8,
            max_new_tokens: int = 512, strict: bool = True) -> dict:
        _track("run", self._track_props())
        if self._stateless:
            self.reset()
        self._count_query()
        response = self._complete(query, max_new_tokens)
        executed = []
        for _ in range(max_steps):
            calls = response.get("function_calls") or []
            if response.get("type") != "call" or not calls:
                break
            ungrounded = _ungrounded_paths(response)
            results = []
            for call in calls:
                name = str(call.get("name"))
                fabricated = sorted(ungrounded.get(name, ()))
                if strict and fabricated:
                    grounded = _grounded_number_paths(
                        call.get("arguments") or {}, query, self._system_text)
                    fabricated = [path for path in fabricated
                                  if path not in grounded]
                if strict and fabricated:
                    results.append({"error": "ungrounded " + ", ".join(fabricated)})
                    continue
                fn = self._functions.get(call.get("name"))
                if fn is None:
                    results.append({"error": "unknown tool: " + name})
                    continue
                try:
                    results.append(fn(**(call.get("arguments") or {})))
                except Exception as exc:
                    results.append({"error": str(exc)})
            executed.extend(results)
            response = self._complete(json.dumps(results, default=_jsonable),
                                      max_new_tokens, ground=False)
        response["results"] = executed
        return response

    def extract(self, text: str, schema: type | dict, max_new_tokens: int = 512,
                strict: bool = True) -> object:
        return extract(text, schema, system=self._system_text or None,
                       max_new_tokens=max_new_tokens, weights=self._weights,
                       strict=strict, generation=self._generation)

    @synchronized
    def reset(self):
        self._bind()
        self._turns = 0
        if self._worker is not None:
            self._worker.reset()
        else:
            runtime._lib(self._generation).cactus_reset()
        self._seen_years = set()

    @synchronized
    def close(self):
        if self._worker is not None:
            try:
                self._worker.close()
            finally:
                self._worker = None
        self._closed = True

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, traceback):
        self.close()

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass


def extract(text: str, schema: type | dict, system: str | None = None,
            max_new_tokens: int = 512, weights: str | None = None,
            strict: bool = True, generation: int | None = None) -> object:
    """One-shot structured extraction using the matching native engine.

    With ``strict=True`` (the default), temporal values that contradict a literal
    year in the input, plus engine-reported fabricated or negated values, raise
    :class:`ExtractionValidationError` instead of being returned silently.
    """
    selected = weights
    generation = _weight_generation(selected) if selected else int(generation or 3)
    _track("extract", {"n_tools": 1, "tuned": bool(selected),
                       "generation": generation})
    agent = Cactus(tools=[schema], system=system, weights=selected, generation=generation)


    facts = agent._system_text
    try:
        response = agent._complete(text, max_new_tokens)
    finally:
        agent.close()
    calls = response.get("function_calls") or response.get("suppressed_calls") or []
    if not calls:
        return None
    arguments = calls[0].get("arguments") or {}
    if strict:
        _validate_extraction(text, schema, arguments, response, facts)
    return schema(**arguments) if _is_pydantic_model(schema) else arguments
"""The shared Cactus engine and its C ABI."""
import ctypes
import os
import warnings
from functools import wraps
import threading

lock = threading.RLock()


def synchronized(function):
    @wraps(function)
    def call(*args, **kwargs):
        with lock:
            return function(*args, **kwargs)
    return call


def bind(lib):
    text, integer = ctypes.c_char_p, ctypes.c_int
    samples = ctypes.POINTER(ctypes.c_float)
    signatures = {
        "load": ([text, ctypes.c_uint64], integer),
        "models": ([], integer),
        "last_error": ([], text),
        "init": ([text, text, text], integer),
        "complete": ([text, samples, integer, integer, text, integer], integer),
        "set_audio": ([text, text, integer], None),
        "set_threads": ([integer], None),
        "reset": ([], None),
        "embed": ([text, samples, integer, samples, integer], integer),
        "transcribe": ([samples, integer, text, text, integer, text, integer], integer),
        "stream_transcribe_process": ([samples, integer, text, text, text, integer], integer),
        "stream_transcribe_stop": ([text, integer], integer),
        "describe": ([text, integer, integer, text, text, text, text, integer], integer),
    }
    for name, (arguments, result) in signatures.items():
        try:
            function = getattr(lib, "cactus_" + name)
        except AttributeError as exc:
            raise RuntimeError("incompatible engine: Cactus 4 requires the cactus_* ABI") from exc
        function.argtypes, function.restype = arguments, result
    return lib


def _library_path(generation=3):
    from . import fetch
    fetch._engine(generation)
    override = os.environ.get("CACTUS_LIB_PATH")
    if override:
        return override
    local = os.path.join(os.path.dirname(os.path.dirname(__file__)), fetch.lib_name())
    if os.path.isfile(local):
        return local
    return fetch.fetch_library(dest_dir=fetch.engine_cache_dir())


def _base_weights_path(generation=3):
    from . import fetch
    return fetch.fetch_weights(generation)


_lib_handles = {}
_active = {}
_loaded_base = {}
_threads = 0


@synchronized
def set_threads(threads):
    global _threads
    if isinstance(threads, bool) or not isinstance(threads, int) or threads < 0:
        raise ValueError("threads must be a whole number, or 0 for the automatic count")
    _threads = threads
    if 3 in _lib_handles:
        _lib_handles[3].cactus_set_threads(threads)


def _load_base(lib, generation):
    if _loaded_base.get(generation):
        return
    path = _base_weights_path(generation)
    with open(path, "rb") as handle:
        data = handle.read()
    if lib.cactus_load(data, len(data)) < 0:
        raise RuntimeError(f"cactus_load failed for {path}")
    _loaded_base[generation] = path
    _active.pop(generation, None)


def _load_cdll(generation):
    """Load the engine, retrying with the other libc build if the first is wrong.

    A musl system that reports itself as glibc (or the reverse) otherwise fails
    at load with a missing symbol such as strtoll_l.
    """
    path = _library_path(generation)
    try:
        return ctypes.CDLL(path)
    except OSError as first:
        from . import fetch

        other = fetch.other_libc_tag()
        if other is None:
            raise
        try:
            alt = fetch.fetch_library(dest_dir=os.path.dirname(path) or ".",
                                      tag=other, generation=generation)
            handle = ctypes.CDLL(alt)
        except Exception:
            raise first from None
        warnings.warn(f"the {fetch._platform_tag()} engine did not load ({first}); "
                      f"using the {other} build instead", stacklevel=3)
        return handle


def _lib(generation=3):
    from . import fetch
    fetch._engine(generation)
    if 3 not in _lib_handles:
        _lib_handles[3] = bind(_load_cdll(3))
        _lib_handles[3].cactus_set_threads(_threads)
    return _lib_handles[3]

"""Pinned engine artifacts and independently versioned model weights."""
import hashlib
import json
import os
import platform
import sysconfig
import sys
import tempfile
import zipfile

WHISTLE = "whistle"
MIRAGE = "mirage"
ENGINE_REPO = "Cactus-Compute/cactus"
ENGINE_VERSION = "4.1.0"
ENGINE_REVISION = "4e822c9036be2eb0e47ef556df32a818bb1572ef"
MANIFEST_SHA256 = "32e182f6f811acde1109084ee5f5c9a606098b95cc8774f27ece8bc1a506de3b"
MODEL_REPOS = {3: "Cactus-Compute/needle3", WHISTLE: "Cactus-Compute/whistle", MIRAGE: "Cactus-Compute/mirage"}
MODEL_REVISIONS = {
    3: "d6c7d6a2e9655505e0f8e23339356dd1705900eb",
    WHISTLE: "741118687e1f008f06d1351a402a731274789790",
    MIRAGE: "76c1e9e53381aca8fc3843c636216c96ff220122",
}
MODEL_SHA256 = {3: 'c9d915eca282ed42d1a09b143b592adb4cc6744ffe2d294adf5cfc5548170c38', 'whistle': 'b6e02f048568ac5d01a2042556c658061e699acbc0aa2a1439f52f3d461dffeb', 'mirage': '4249a0f7515272ff76b9414bec17d7e7daf84b15b66c7fb4f17fce1e66f9f237'}
BASE_WEIGHTS = {3: "needle3.cact", WHISTLE: "whistle.cact", MIRAGE: "mirage.cact"}
CHECKPOINT_PREFIX = "checkpoints"
WHEEL_TAGS = ("macosx_11_0_arm64", "macosx_11_0_x86_64", "manylinux2014_aarch64", "manylinux2014_x86_64",
              "musllinux_1_2_aarch64", "musllinux_1_2_x86_64", "win_amd64", "win_arm64")
PLATFORMS = ("macos-arm64", "linux-x86_64", "linux-arm64", "linux-armv7", "linux-riscv64", "linux-mipsel",
             "windows-x86_64", "windows-arm64", "android-arm64", "android-armv7", "android-riscv64",
             "ios-arm64", "ios-sim-arm64", "tvos-arm64", "watchos-arm64", "wasm", "wasm-component")


def _engine(generation=3):
    if str(generation) == "3":
        return 3
    if generation in (WHISTLE, MIRAGE):
        return generation
    raise ValueError(f"unsupported model: {generation}; Needle 2 requires cactus-compute<4 from the legacy branch")


def _lib_name_for(tag):
    return "libcactus." + ("dylib" if tag.startswith("macosx") else "dll" if tag.startswith("win") else "so")


def _lib_name():
    return "libcactus." + ("dylib" if sys.platform == "darwin" else "dll" if sys.platform == "win32" else "so")


def lib_name(generation=3, tag=None):
    _engine(generation)
    return _lib_name_for(tag) if tag else _lib_name()


def lib_path_env(generation=3):
    _engine(generation)
    return "CACTUS_LIB_PATH"


def _loaded_libc():
    try:
        with open("/proc/self/maps", "rb") as maps:
            blob = maps.read()
    except OSError:
        return None
    if b"musl" in blob:
        return "musl"
    if b"/libc.so.6" in blob or b"/ld-linux" in blob:
        return "glibc"
    return None


def _is_musl():
    """True on a musl system (Alpine and friends).

    platform.libc_ver() scans the interpreter binary and reports glibc on some
    musl builds, so the loader and the filesystem are asked first.
    """
    if sys.platform != "linux":
        return False
    libc = _loaded_libc()
    if libc:
        return libc == "musl"
    import glob
    if glob.glob("/lib/ld-musl-*.so.1"):
        return True
    if glob.glob("/lib*/libc.so.6") or glob.glob("/lib/*-linux-gnu/libc.so.6"):
        return False
    if "musl" in (sysconfig.get_config_var("HOST_GNU_TYPE") or ""):
        return True
    libc, _ = platform.libc_ver()
    return not libc


_ENGINE_ARCHES = {"x86_64": "x86_64", "amd64": "x86_64", "aarch64": "aarch64", "arm64": "aarch64"}


def _is_android():
    """Android reports itself as Linux but links Bionic, where no published engine loads.

    Termux is the usual way this is reached.  ``platform.libc_ver()`` finds no glibc
    there, so the Linux path would pick the musl aarch64 wheel and fail to load it.
    """
    if hasattr(sys, "getandroidapilevel"):
        return True
    if _loaded_libc():
        return False
    return bool(os.environ.get("ANDROID_ROOT") and os.environ.get("ANDROID_DATA"))


def _platform_tag():
    machine = platform.machine().lower()
    if sys.platform == "darwin":
        arch = "arm64" if machine in ("arm64", "aarch64") else "x86_64"
        return "macosx_11_0_" + arch
    if _is_android():
        raise RuntimeError(
            "no Cactus engine wheel is published for Android (Bionic): the Linux wheels link "
            "glibc or musl, so libcactus fails to load with a missing libm.so.6. The Android "
            "builds ship a static library and the cactus CLI (cactus download android-arm64), "
            "not a shared library for ctypes; to use the Python API here, build a shared "
            "libcactus for Bionic and point CACTUS_LIB_PATH at it.")
    arch = _ENGINE_ARCHES.get(machine)
    if arch is None:


        system = "Windows" if sys.platform == "win32" else "Linux"
        raise RuntimeError(
            f"no Cactus engine is published for {system} on {platform.machine() or 'this machine'}; "
            "the engine builds are for x86_64 and arm64. Build libcactus for this machine "
            "and point CACTUS_LIB_PATH at it.")
    if sys.platform == "win32":
        return "win_arm64" if arch == "aarch64" else "win_amd64"
    family = "musllinux_1_2_" if _is_musl() else "manylinux2014_"
    return family + arch


def other_libc_tag():
    """The tag for the other Linux libc family, or None off Linux."""
    tag = _platform_tag()
    if tag.startswith("manylinux2014_"):
        return tag.replace("manylinux2014_", "musllinux_1_2_")
    if tag.startswith("musllinux_1_2_"):
        return tag.replace("musllinux_1_2_", "manylinux2014_")
    return None


def engine_repo(generation=3):
    _engine(generation)
    return ENGINE_REPO


def engine_version(generation=3):
    _engine(generation)
    return ENGINE_VERSION


def repo_prefix(generation=3):
    _engine(generation)
    return f"releases/{ENGINE_VERSION}/"


def engine_wheel(version, tag, generation=3):
    _engine(generation)
    return f"releases/{version}/python/cactus_runtime-{version}-py3-none-{tag}.whl"


def _cache_root():
    return os.path.join(os.environ.get("XDG_CACHE_HOME", os.path.expanduser("~/.cache")), "cactus")


def engine_cache_dir():
    return os.path.join(_cache_root(), "engine", ENGINE_VERSION, ENGINE_REVISION)


def cache_dir(generation=3):
    key = _engine(generation)
    return os.path.join(_cache_root(), "models", BASE_WEIGHTS[key][:-5], MODEL_REVISIONS[key])


def base_weights(generation=3):
    return BASE_WEIGHTS[_engine(generation)]


def _sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def _atomic_write(path, data):
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=".cactus-", dir=os.path.dirname(os.path.abspath(path)))
    try:
        with os.fdopen(fd, "wb") as target:
            target.write(data)
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return path


def _manifest():
    from huggingface_hub import hf_hub_download
    if len(ENGINE_REVISION) != 40 or len(MANIFEST_SHA256) != 64:
        raise RuntimeError("this Cactus client has no verified engine release pin")
    path = hf_hub_download(repo_id=ENGINE_REPO, filename=repo_prefix() + "manifest.json", revision=ENGINE_REVISION)
    if _sha256(path) != MANIFEST_SHA256:
        raise RuntimeError("engine release manifest checksum mismatch")
    with open(path) as source:
        manifest = json.load(source)
    if manifest.get("version") != ENGINE_VERSION or manifest.get("api") != "cactus":
        raise RuntimeError("incompatible engine release manifest")
    return manifest


def _artifact(filename):
    from huggingface_hub import hf_hub_download
    manifest = _manifest()
    entry = manifest["files"][filename]
    path = hf_hub_download(repo_id=ENGINE_REPO, filename=repo_prefix() + filename, revision=ENGINE_REVISION)
    if os.path.getsize(path) != entry["size"] or _sha256(path) != entry["sha256"]:
        raise RuntimeError(f"engine artifact checksum mismatch: {filename}")
    return path


def unpublished_engine_wheels():
    """Validate every pinned runtime wheel's remote checksum before a client release."""
    from huggingface_hub import HfApi
    manifest = _manifest()
    paths = [engine_wheel(ENGINE_VERSION, tag) for tag in WHEEL_TAGS]
    entries = {entry.path: entry for entry in HfApi().get_paths_info(ENGINE_REPO, paths, revision=ENGINE_REVISION)}
    missing = []
    for path in paths:
        entry = entries.get(path)
        expected = manifest["files"].get(path[len(repo_prefix()):])
        if not entry or not expected or entry.size != expected["size"]:
            missing.append(ENGINE_REPO + "/" + path)
            continue
        if entry.lfs:
            valid = entry.lfs.sha256 == expected["sha256"]
        else:
            try:
                _artifact(path[len(repo_prefix()):])
                valid = True
            except RuntimeError:
                valid = False
        if not valid:
            missing.append(ENGINE_REPO + "/" + path)
    return missing


def _register_download(generation=3):
    from huggingface_hub import hf_hub_download
    key = _engine(generation)
    try:
        hf_hub_download(repo_id=MODEL_REPOS[key], filename="config.json", revision=MODEL_REVISIONS[key], force_download=True)
    except Exception:
        pass


def download_platform(name, out_dir, generation=3, dest=None):
    _engine(generation)
    if name not in PLATFORMS:
        raise ValueError(f"unsupported platform: {name}")
    manifest = _manifest()
    files = [path for path in manifest["files"] if path.startswith(name + "/")]
    if not files:
        raise FileNotFoundError(f"{name} is missing from the pinned engine release")
    dest = dest or os.path.join(out_dir, name)
    outputs = []
    for filename in files:
        cached = _artifact(filename)
        target = os.path.join(dest, os.path.basename(filename))
        with open(cached, "rb") as source:
            _atomic_write(target, source.read())
        if os.path.basename(target) in ("cactus", "cactus.exe"):
            os.chmod(target, os.stat(target).st_mode | 0o111)
        outputs.append(target)
    return outputs


def fetch_weights(generation=3, dest_dir=None, force=False):
    from huggingface_hub import hf_hub_download
    key = _engine(generation)
    override = os.environ.get("CACTUS_" + ("NEEDLE" if key == 3 else key.upper()) + "_WEIGHTS")
    if override:
        return os.fspath(override)
    _register_download(key)
    name = base_weights(key)
    dest_dir = dest_dir or cache_dir(key)
    out = os.path.join(dest_dir, name)
    expected = MODEL_SHA256.get(key)
    if os.path.exists(out) and not force and expected and _sha256(out) == expected:
        return out
    cached = hf_hub_download(repo_id=MODEL_REPOS[key], filename=name, revision=MODEL_REVISIONS[key], force_download=force)
    if expected and _sha256(cached) != expected:
        raise RuntimeError(f"model checksum mismatch: {name}")
    with open(cached, "rb") as source:
        return _atomic_write(out, source.read())


def fetch_checkpoint(name, dest_dir, generation=3, force=False):
    from huggingface_hub import hf_hub_download
    from huggingface_hub.errors import EntryNotFoundError
    key = _engine(generation)
    _register_download(key)
    base = os.path.basename(name)
    for candidate in (f"{CHECKPOINT_PREFIX}/{base}", base):
        try:
            cached = hf_hub_download(repo_id=MODEL_REPOS[key], filename=candidate, revision=MODEL_REVISIONS[key], force_download=force)
            with open(cached, "rb") as source:
                return _atomic_write(os.path.join(dest_dir, base), source.read())
        except EntryNotFoundError:
            continue
    raise FileNotFoundError(f"{base} is not published in {MODEL_REPOS[key]}")


def fetch_library(version=None, dest_dir=None, tag=None, generation=3):
    _engine(generation)
    if version is not None and version != ENGINE_VERSION:
        raise ValueError("only the pinned engine version can be downloaded")
    tag = tag or _platform_tag()
    if tag not in WHEEL_TAGS:
        raise ValueError(f"unsupported wheel tag: {tag}")
    path = _artifact(f"python/cactus_runtime-{ENGINE_VERSION}-py3-none-{tag}.whl")
    member = "cactus/" + lib_name(tag=tag)
    with zipfile.ZipFile(path) as archive:
        data = archive.read(member)
    out = os.path.join(dest_dir or engine_cache_dir(), lib_name(tag=tag))
    if not os.path.isfile(out) or _sha256(out) != hashlib.sha256(data).hexdigest():
        _atomic_write(out, data)
    return out
from __future__ import annotations

import enum
import inspect
import re
import types
import typing
from typing import Callable

_JSON_TYPES = {str: "string", int: "integer", float: "number", bool: "boolean",
               list: "array", dict: "object"}


_UNION_ORIGINS = (typing.Union, getattr(types, "UnionType", typing.Union))

_MISSING = object()


class Field:
    def __init__(self, default=_MISSING, *, description=None, enum=None, const=_MISSING,
                 ge=None, le=None, gt=None, lt=None, multiple_of=None,
                 min_length=None, max_length=None, pattern=None, format=None,
                 min_items=None, max_items=None, unique_items=None):
        self.default = default
        self.description = description
        self.enum = enum
        self.const = const
        self.ge, self.le, self.gt, self.lt = ge, le, gt, lt
        self.multiple_of = multiple_of
        self.min_length, self.max_length = min_length, max_length
        self.pattern, self.format = pattern, format
        self.min_items, self.max_items, self.unique_items = min_items, max_items, unique_items

    def has_default(self):
        return self.default is not _MISSING

    def apply(self, schema):
        pairs = (("description", self.description), ("enum", self.enum),
                 ("minimum", self.ge), ("maximum", self.le),
                 ("exclusiveMinimum", self.gt), ("exclusiveMaximum", self.lt),
                 ("multipleOf", self.multiple_of), ("minLength", self.min_length),
                 ("maxLength", self.max_length), ("pattern", self.pattern),
                 ("format", self.format), ("minItems", self.min_items),
                 ("maxItems", self.max_items), ("uniqueItems", self.unique_items))
        for key, value in pairs:
            if value is not None:
                schema[key] = list(value) if key == "enum" else value
        if self.const is not _MISSING:
            schema["const"] = self.const
        return schema


def _is_optional(annotation):
    if typing.get_origin(annotation) is typing.Annotated:
        return _is_optional(typing.get_args(annotation)[0])
    return (typing.get_origin(annotation) in _UNION_ORIGINS
            and type(None) in typing.get_args(annotation))


def _json_type(annotation, defs):
    if annotation is inspect.Parameter.empty or annotation is None:
        return {"type": "string"}
    origin = typing.get_origin(annotation)
    if origin is typing.Annotated:
        return _json_type(typing.get_args(annotation)[0], defs)
    if origin is None:
        if annotation in _JSON_TYPES:
            return {"type": _JSON_TYPES[annotation]}
        if isinstance(annotation, type) and issubclass(annotation, enum.Enum):
            values = [e.value for e in annotation]
            val_type = _JSON_TYPES.get(type(values[0]), "string") if values else "string"
            return {"type": val_type, "enum": values}
        if _is_pydantic_model(annotation):
            schema = pydantic_schema(annotation)["parameters"]
            for key in ("$defs", "definitions"):
                if key in schema:
                    defs.setdefault(key, {}).update(schema.pop(key))
            return schema
        return {"type": "string"}
    if origin is typing.Literal:
        args = list(typing.get_args(annotation))
        val_type = _JSON_TYPES.get(type(args[0]), "string") if args else "string"
        return {"type": val_type, "enum": args}
    if origin in (list, typing.List):
        args = typing.get_args(annotation)
        return {"type": "array", "items": _json_type(args[0], defs) if args else {"type": "string"}}
    if origin in (dict, typing.Dict):
        return {"type": "object"}
    if origin in _UNION_ORIGINS:
        rest = [a for a in typing.get_args(annotation) if a is not type(None)]
        if rest:
            return _json_type(rest[0], defs)
    return {"type": "string"}


def _field_of(annotation, default):
    if isinstance(default, Field):
        return default
    origin = typing.get_origin(annotation)
    if origin is typing.Annotated:
        for meta in typing.get_args(annotation)[1:]:
            if isinstance(meta, Field):
                return meta
    if origin in _UNION_ORIGINS:
        rest = [a for a in typing.get_args(annotation) if a is not type(None)]
        if len(rest) == 1:
            return _field_of(rest[0], _MISSING)
    return None


def _parse_doc(doc):
    if not doc:
        return "", {}
    lines = doc.strip("\n").splitlines()
    heads = ("args:", "arguments:", "parameters:", "params:")
    desc, args, i = [], {}, 0
    while i < len(lines) and lines[i].strip().lower() not in heads:
        desc.append(lines[i].strip())
        i += 1
    head = _indent(lines[i]) if i < len(lines) else 0
    name, depth = None, 0
    for line in lines[i + 1:]:
        if not line.strip():
            continue

        if _indent(line) <= head and re.match(r"\s*[A-Za-z][\w ]*:\s*$", line):
            break
        m = re.match(r"\s+(\w+)\s*(?:\([^)]*\))?\s*:\s*(.+)", line)
        if m and (name is None or _indent(line) <= depth):
            name, depth = m.group(1), _indent(line)
            args[name] = m.group(2).strip()
        elif name and _indent(line) > depth:


            args[name] += " " + line.strip()
    return " ".join(w for w in desc if w).strip(), args


def _indent(line):
    return len(line) - len(line.lstrip())


def build_schema(fn: Callable) -> dict:
    signature = inspect.signature(fn)
    try:
        hints = typing.get_type_hints(fn, include_extras=True)
    except Exception:
        hints = {}
    description, arg_docs = _parse_doc(fn.__doc__)
    properties, required, defs = {}, [], {}

from __future__ import annotations

import ctypes
import json
import os
import warnings

from .._telemetry import track as _track
from . import runtime
from .runtime import synchronized
from .tools import build_schema, pydantic_schema, _is_pydantic_model
from .grounding import (
    _jsonable, _source_years,
    _with_date_fact, _annotate_ungrounded, _validate_extraction,
    _ungrounded_paths, _grounded_number_paths,
)

UNRESET_TURNS = 4


_CACT_GENERATIONS = {
    0x05E12A83: 2,
    0x05E12A84: 3,
}


def _weight_generation(path):
    with open(path, "rb") as handle:
        tag_bytes = handle.read(4)
    if len(tag_bytes) != 4:
        raise RuntimeError(f"{path} is not a complete .cact archive")
    tag = int.from_bytes(tag_bytes, "little")
    try:
        return _CACT_GENERATIONS[tag]
    except KeyError as exc:
        raise RuntimeError(
            f"{path} has unknown .cact format tag 0x{tag:08x}; "
            "cannot choose a compatible Needle engine") from exc


_CACT_HEADER = "<48If"
_CACT_RECORD = "<BBHIIIIQQII"
_CACT_FP16, _CACT_RAW = 1, 4
_CONFIDENCE_HEAD_CODE = 2


def _confidence_head_present(path):
    """Whether a Needle 3 archive carries a confidence head, read from its head manifest."""
    import struct

    with open(path, "rb") as handle:
        header = handle.read(struct.calcsize(_CACT_HEADER))
        if len(header) < struct.calcsize(_CACT_HEADER):
            return False
        fields = struct.unpack(_CACT_HEADER, header)
        num_tensors, codebook = fields[1], fields[2]
        handle.seek(codebook * 4, 1)
        size = struct.calcsize(_CACT_RECORD)
        records = [struct.unpack(_CACT_RECORD, handle.read(size)) for _ in range(num_tensors)]
        if not records or records[-1][0] != _CACT_RAW:
            return False
        for heads in (1, 2, 3):
            index = num_tensors - 2 - 6 * heads
            if index < 0:
                continue
            dtype, ndim, _, length = records[index][:4]
            if dtype != _CACT_FP16 or ndim != 1 or length != heads:
                continue
            handle.seek(records[index][7])
            codes = struct.unpack(f"<{heads}e", handle.read(2 * heads))
            return _CONFIDENCE_HEAD_CODE in {int(round(c)) for c in codes}
    return False


class Cactus:
    def __init__(self, tools=None, system=None, weights=None, tool_index_path=None, buffer_size=65536,
                 auto_date=True, generation=None, stateless=False):
        self._functions = {}
        self._stateless = bool(stateless)
        self._turns = 0
        self._weights = os.fspath(weights) if weights is not None else None
        self._tuned = self._weights is not None
        if self._tuned:
            self._generation = _weight_generation(self._weights)
        else:
            self._generation = int(generation or 3)
        from . import fetch
        fetch._engine(self._generation)
        self._worker = None
        self._closed = False
        self._calibrated = (not self._tuned
                            or (self._generation >= 3 and _confidence_head_present(self._weights)))
        if not self._calibrated:
            warnings.warn("these weights carry no confidence head trained for them, so this "
                          "agent reports confidence as None; platform fine-tunes keep the head",
                          stacklevel=2)
        self._system_text = _with_date_fact(system or "") if auto_date else (system or "")
        self._system = self._system_text.encode("utf-8")
        tools_json = tools if isinstance(tools, str) else json.dumps(self._resolve(tools))
        self._tools_json = tools_json.encode("utf-8")
        try:
            parsed_tools = json.loads(tools_json)
            self._n_tools = len(parsed_tools)
        except (json.JSONDecodeError, TypeError):
            parsed_tools, self._n_tools = [], None
        self._tool_schemas = [entry for entry in (parsed_tools or [])
                              if isinstance(entry, dict)]
        self._seen_years = set()
        self._tool_index_path = (os.fspath(tool_index_path).encode("utf-8")
                                 if tool_index_path else None)
        self._buffer = ctypes.create_string_buffer(buffer_size)
        if self._weights:
            from .._worker import FineTuneWorker
            self._worker = FineTuneWorker(
                runtime._library_path(self._generation), self._weights,
                self._system.decode("utf-8"), self._tools_json.decode("utf-8"),
                os.fspath(tool_index_path) if tool_index_path else None,
                buffer_size)
        else:
            self._bind()

    @synchronized
    def _bind(self):
        if self._closed:
            raise RuntimeError("Cactus instance is closed")
        if self._worker is not None:
            return
        generation = self._generation
        lib = runtime._lib(generation)
        runtime._load_base(lib, generation)
        if runtime._active.get(generation) is self:
            return
        if lib.cactus_init(self._system, self._tools_json, self._tool_index_path) < 0:
            runtime._active.pop(generation, None)
            raise RuntimeError("cactus_init failed")
        runtime._active[generation] = self
        self._seen_years = set()

    def _resolve(self, tools):
        schemas = []
        for entry in tools or []:
            if _is_pydantic_model(entry):
                schema = pydantic_schema(entry)
                self._functions[schema["name"]] = entry
                schemas.append(schema)
            elif callable(entry):
                schema = getattr(entry, "_cactus_tool", None) or build_schema(entry)
                self._functions[schema["name"]] = entry
                schemas.append(schema)
            elif isinstance(entry, dict):
                schemas.append(entry)
        return schemas

    def _track_props(self):
        return {"n_tools": self._n_tools, "tuned": self._tuned,
                "generation": self._generation}

    @synchronized
    def complete(self, text: str = "", max_new_tokens: int = 512, *, audio=None, language=None,
                 keywords=None, word_timestamps=False) -> dict:
        _track("complete", self._track_props())
        if self._stateless:
            self.reset()
        if audio is not None and text:
            raise ValueError("complete accepts either text or audio")
        self._count_query()
        if audio is not None:
            return self._complete_audio(audio, max_new_tokens, language, keywords, word_timestamps)
        return self._complete(text, max_new_tokens)

    def _count_query(self):
        self._turns += 1
        if self._turns == UNRESET_TURNS + 1:
            warnings.warn(
                f"{UNRESET_TURNS} queries on this agent without reset(): every turn stays in "
                "the conversation, so unrelated queries lose accuracy and confidence. "
                "Call reset() between independent queries, or construct with stateless=True",
                stacklevel=3)

    @synchronized
    def _complete(self, text: str, max_new_tokens: int = 512,
                  ground: bool = True) -> dict:
        self._bind()
        self._seen_years |= _source_years(text or "")
        if self._worker is not None:
            raw = self._worker.complete(text, max_new_tokens)
        else:
            lib = runtime._lib(self._generation)
            audio = (None, 0)
            rc = lib.cactus_complete(
                text.encode("utf-8"), *audio, int(max_new_tokens), self._buffer,
                len(self._buffer))
            if rc < 0:
                detail = self._buffer.value.decode("utf-8", "replace")
                raise RuntimeError(detail or f"cactus_complete failed (code {rc})")
            raw = self._buffer.value.decode("utf-8")
        return self._response(raw, text, ground)

    def _complete_audio(self, audio, max_new_tokens, language, keywords, word_timestamps):
        from .audio import _samples, _options
        from .whistle import Whistle, _weights_path
        self._bind()
        samples, count = _samples(audio)
        if keywords is not None and not isinstance(keywords, str):
            keywords = "\n".join(keywords)
        if self._worker is not None:
            packed = ctypes.string_at(samples, count * ctypes.sizeof(ctypes.c_float))
            raw = self._worker.complete_audio(packed, _weights_path(), language, keywords, word_timestamps, max_new_tokens)
        else:
            speech = Whistle()
            lib = speech._bind()
            language, keywords = _options(language, keywords)
            lib.cactus_set_audio(language, keywords, int(bool(word_timestamps)))
            code = lib.cactus_complete(None, samples, count, int(max_new_tokens), self._buffer, len(self._buffer))
            if code < 0:
                raise RuntimeError(lib.cactus_last_error().decode("utf-8", "replace"))
            raw = self._buffer.value.decode("utf-8")
        response = json.loads(raw)
        heard = response.get("audio_text", "")
        self._seen_years |= _source_years(heard)
        return self._response(raw, heard)

    def _response(self, raw, text, ground=True):
        try:
            response = json.loads(raw)
        except json.JSONDecodeError as err:
            raise RuntimeError(
                f"engine returned an unparseable envelope ({err}); this is an "
                f"engine bug - please report it with the prompt and schema") from err
        if not self._calibrated:
            response["confidence"] = None
        if ground:
            _annotate_ungrounded(response, self._tool_schemas, self._seen_years,
                                 self._system_text, text)
        return response

    @synchronized
    def embed(self, text: str = "") -> list[float]:
        self._bind()
        if self._worker is not None:
            return self._worker.embed(text)
        lib = runtime._lib(self._generation)
        dim = lib.cactus_embed(text.encode("utf-8"), None, 0, None, 0)
        if dim <= 0:
            raise RuntimeError(f"cactus_embed failed (code {dim})")
        output = (ctypes.c_float * dim)()
        rc = lib.cactus_embed(text.encode("utf-8"), None, 0, output, dim)
        if rc != dim:
            raise RuntimeError(f"cactus_embed failed (code {rc})")
        return list(output)

    def run(self, query: str = "", max_steps: int = 8,
            max_new_tokens: int = 512, strict: bool = True) -> dict:
        _track("run", self._track_props())
        if self._stateless:
            self.reset()
        self._count_query()
        response = self._complete(query, max_new_tokens)
        executed = []
        for _ in range(max_steps):
            calls = response.get("function_calls") or []
            if response.get("type") != "call" or not calls:
                break
            ungrounded = _ungrounded_paths(response)
            results = []
            for call in calls:
                name = str(call.get("name"))
                fabricated = sorted(ungrounded.get(name, ()))
                if strict and fabricated:
                    grounded = _grounded_number_paths(
                        call.get("arguments") or {}, query, self._system_text)
                    fabricated = [path for path in fabricated
                                  if path not in grounded]
                if strict and fabricated:
                    results.append({"error": "ungrounded " + ", ".join(fabricated)})
                    continue
                fn = self._functions.get(call.get("name"))
                if fn is None:
                    results.append({"error": "unknown tool: " + name})
                    continue
                try:
                    results.append(fn(**(call.get("arguments") or {})))
                except Exception as exc:
                    results.append({"error": str(exc)})
            executed.extend(results)
            response = self._complete(json.dumps(results, default=_jsonable),
                                      max_new_tokens, ground=False)
        response["results"] = executed
        return response

    def extract(self, text: str, schema: type | dict, max_new_tokens: int = 512,
                strict: bool = True) -> object:
        return extract(text, schema, system=self._system_text or None,
                       max_new_tokens=max_new_tokens, weights=self._weights,
                       strict=strict, generation=self._generation)

    @synchronized
    def reset(self):
        self._bind()
        self._turns = 0
        if self._worker is not None:
            self._worker.reset()
        else:
            runtime._lib(self._generation).cactus_reset()
        self._seen_years = set()

    @synchronized
    def close(self):
        if self._worker is not None:
            try:
                self._worker.close()
            finally:
                self._worker = None
        self._closed = True

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, traceback):
        self.close()

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass


def extract(text: str, schema: type | dict, system: str | None = None,
            max_new_tokens: int = 512, weights: str | None = None,
            strict: bool = True, generation: int | None = None) -> object:
    """One-shot structured extraction using the matching native engine.

    With ``strict=True`` (the default), temporal values that contradict a literal
    year in the input, plus engine-reported fabricated or negated values, raise
    :class:`ExtractionValidationError` instead of being returned silently.
    """
    selected = weights
    generation = _weight_generation(selected) if selected else int(generation or 3)
    _track("extract", {"n_tools": 1, "tuned": bool(selected),
                       "generation": generation})
    agent = Cactus(tools=[schema], system=system, weights=selected, generation=generation)


    facts = agent._system_text
    try:
        response = agent._complete(text, max_new_tokens)
    finally:
        agent.close()
    calls = response.get("function_calls") or response.get("suppressed_calls") or []
    if not calls:
        return None
    arguments = calls[0].get("arguments") or {}
    if strict:
        _validate_extraction(text, schema, arguments, response, facts)
    return schema(**arguments) if _is_pydantic_model(schema) else arguments
"""The shared Cactus engine and its C ABI."""
import ctypes
import os
import warnings
from functools import wraps
import threading

lock = threading.RLock()


def synchronized(function):
    @wraps(function)
    def call(*args, **kwargs):
        with lock:
            return function(*args, **kwargs)
    return call


def bind(lib):
    text, integer = ctypes.c_char_p, ctypes.c_int
    samples = ctypes.POINTER(ctypes.c_float)
    signatures = {
        "load": ([text, ctypes.c_uint64], integer),
        "models": ([], integer),
        "last_error": ([], text),
        "init": ([text, text, text], integer),
        "complete": ([text, samples, integer, integer, text, integer], integer),
        "set_audio": ([text, text, integer], None),
        "set_threads": ([integer], None),
        "reset": ([], None),
        "embed": ([text, samples, integer, samples, integer], integer),
        "transcribe": ([samples, integer, text, text, integer, text, integer], integer),
        "stream_transcribe_process": ([samples, integer, text, text, text, integer], integer),
        "stream_transcribe_stop": ([text, integer], integer),
        "describe": ([text, integer, integer, text, text, text, text, integer], integer),
    }
    for name, (arguments, result) in signatures.items():
        try:
            function = getattr(lib, "cactus_" + name)
        except AttributeError as exc:
            raise RuntimeError("incompatible engine: Cactus 4 requires the cactus_* ABI") from exc
        function.argtypes, function.restype = arguments, result
    return lib


def _library_path(generation=3):
    from . import fetch
    fetch._engine(generation)
    override = os.environ.get("CACTUS_LIB_PATH")
    if override:
        return override
    local = os.path.join(os.path.dirname(os.path.dirname(__file__)), fetch.lib_name())
    if os.path.isfile(local):
        return local
    return fetch.fetch_library(dest_dir=fetch.engine_cache_dir())


def _base_weights_path(generation=3):
    from . import fetch
    return fetch.fetch_weights(generation)


_lib_handles = {}
_active = {}
_loaded_base = {}
_threads = 0


@synchronized
def set_threads(threads):
    global _threads
    if isinstance(threads, bool) or not isinstance(threads, int) or threads < 0:
        raise ValueError("threads must be a whole number, or 0 for the automatic count")
    _threads = threads
    if 3 in _lib_handles:
        _lib_handles[3].cactus_set_threads(threads)


def _load_base(lib, generation):
    if _loaded_base.get(generation):
        return
    path = _base_weights_path(generation)
    with open(path, "rb") as handle:
        data = handle.read()
    if lib.cactus_load(data, len(data)) < 0:
        raise RuntimeError(f"cactus_load failed for {path}")
    _loaded_base[generation] = path
    _active.pop(generation, None)


def _load_cdll(generation):
    """Load the engine, retrying with the other libc build if the first is wrong.

    A musl system that reports itself as glibc (or the reverse) otherwise fails
    at load with a missing symbol such as strtoll_l.
    """
    path = _library_path(generation)
    try:
        return ctypes.CDLL(path)
    except OSError as first:
        from . import fetch

        other = fetch.other_libc_tag()
        if other is None:
            raise
        try:
            alt = fetch.fetch_library(dest_dir=os.path.dirname(path) or ".",
                                      tag=other, generation=generation)
            handle = ctypes.CDLL(alt)
        except Exception:
            raise first from None
        warnings.warn(f"the {fetch._platform_tag()} engine did not load ({first}); "
                      f"using the {other} build instead", stacklevel=3)
        return handle


def _lib(generation=3):
    from . import fetch
    fetch._engine(generation)
    if 3 not in _lib_handles:
        _lib_handles[3] = bind(_load_cdll(3))
        _lib_handles[3].cactus_set_threads(_threads)
    return _lib_handles[3]

"""Pinned engine artifacts and independently versioned model weights."""
import hashlib
import json
import os
import platform
import sysconfig
import sys
import tempfile
import zipfile

WHISTLE = "whistle"
MIRAGE = "mirage"
ENGINE_REPO = "Cactus-Compute/cactus"
ENGINE_VERSION = "4.1.0"
ENGINE_REVISION = "4e822c9036be2eb0e47ef556df32a818bb1572ef"
MANIFEST_SHA256 = "32e182f6f811acde1109084ee5f5c9a606098b95cc8774f27ece8bc1a506de3b"
MODEL_REPOS = {3: "Cactus-Compute/needle3", WHISTLE: "Cactus-Compute/whistle", MIRAGE: "Cactus-Compute/mirage"}
MODEL_REVISIONS = {
    3: "d6c7d6a2e9655505e0f8e23339356dd1705900eb",
    WHISTLE: "741118687e1f008f06d1351a402a731274789790",
    MIRAGE: "76c1e9e53381aca8fc3843c636216c96ff220122",
}
MODEL_SHA256 = {3: 'c9d915eca282ed42d1a09b143b592adb4cc6744ffe2d294adf5cfc5548170c38', 'whistle': 'b6e02f048568ac5d01a2042556c658061e699acbc0aa2a1439f52f3d461dffeb', 'mirage': '4249a0f7515272ff76b9414bec17d7e7daf84b15b66c7fb4f17fce1e66f9f237'}
BASE_WEIGHTS = {3: "needle3.cact", WHISTLE: "whistle.cact", MIRAGE: "mirage.cact"}
CHECKPOINT_PREFIX = "checkpoints"
WHEEL_TAGS = ("macosx_11_0_arm64", "macosx_11_0_x86_64", "manylinux2014_aarch64", "manylinux2014_x86_64",
              "musllinux_1_2_aarch64", "musllinux_1_2_x86_64", "win_amd64", "win_arm64")
PLATFORMS = ("macos-arm64", "linux-x86_64", "linux-arm64", "linux-armv7", "linux-riscv64", "linux-mipsel",
             "windows-x86_64", "windows-arm64", "android-arm64", "android-armv7", "android-riscv64",
             "ios-arm64", "ios-sim-arm64", "tvos-arm64", "watchos-arm64", "wasm", "wasm-component")


def _engine(generation=3):
    if str(generation) == "3":
        return 3
    if generation in (WHISTLE, MIRAGE):
        return generation
    raise ValueError(f"unsupported model: {generation}; Needle 2 requires cactus-compute<4 from the legacy branch")


def _lib_name_for(tag):
    return "libcactus." + ("dylib" if tag.startswith("macosx") else "dll" if tag.startswith("win") else "so")


def _lib_name():
    return "libcactus." + ("dylib" if sys.platform == "darwin" else "dll" if sys.platform == "win32" else "so")


def lib_name(generation=3, tag=None):
    _engine(generation)
    return _lib_name_for(tag) if tag else _lib_name()


def lib_path_env(generation=3):
    _engine(generation)
    return "CACTUS_LIB_PATH"


def _loaded_libc():
    try:
        with open("/proc/self/maps", "rb") as maps:
            blob = maps.read()
    except OSError:
        return None
    if b"musl" in blob:
        return "musl"
    if b"/libc.so.6" in blob or b"/ld-linux" in blob:
        return "glibc"
    return None


def _is_musl():
    """True on a musl system (Alpine and friends).

    platform.libc_ver() scans the interpreter binary and reports glibc on some
    musl builds, so the loader and the filesystem are asked first.
    """
    if sys.platform != "linux":
        return False
    libc = _loaded_libc()
    if libc:
        return libc == "musl"
    import glob
    if glob.glob("/lib/ld-musl-*.so.1"):
        return True
    if glob.glob("/lib*/libc.so.6") or glob.glob("/lib/*-linux-gnu/libc.so.6"):
        return False
    if "musl" in (sysconfig.get_config_var("HOST_GNU_TYPE") or ""):
        return True
    libc, _ = platform.libc_ver()
    return not libc


_ENGINE_ARCHES = {"x86_64": "x86_64", "amd64": "x86_64", "aarch64": "aarch64", "arm64": "aarch64"}


def _is_android():
    """Android reports itself as Linux but links Bionic, where no published engine loads.

    Termux is the usual way this is reached.  ``platform.libc_ver()`` finds no glibc
    there, so the Linux path would pick the musl aarch64 wheel and fail to load it.
    """
    if hasattr(sys, "getandroidapilevel"):
        return True
    if _loaded_libc():
        return False
    return bool(os.environ.get("ANDROID_ROOT") and os.environ.get("ANDROID_DATA"))


def _platform_tag():
    machine = platform.machine().lower()
    if sys.platform == "darwin":
        arch = "arm64" if machine in ("arm64", "aarch64") else "x86_64"
        return "macosx_11_0_" + arch
    if _is_android():
        raise RuntimeError(
            "no Cactus engine wheel is published for Android (Bionic): the Linux wheels link "
            "glibc or musl, so libcactus fails to load with a missing libm.so.6. The Android "
            "builds ship a static library and the cactus CLI (cactus download android-arm64), "
            "not a shared library for ctypes; to use the Python API here, build a shared "
            "libcactus for Bionic and point CACTUS_LIB_PATH at it.")
    arch = _ENGINE_ARCHES.get(machine)
    if arch is None:


        system = "Windows" if sys.platform == "win32" else "Linux"
        raise RuntimeError(
            f"no Cactus engine is published for {system} on {platform.machine() or 'this machine'}; "
            "the engine builds are for x86_64 and arm64. Build libcactus for this machine "
            "and point CACTUS_LIB_PATH at it.")
    if sys.platform == "win32":
        return "win_arm64" if arch == "aarch64" else "win_amd64"
    family = "musllinux_1_2_" if _is_musl() else "manylinux2014_"
    return family + arch


def other_libc_tag():
    """The tag for the other Linux libc family, or None off Linux."""
    tag = _platform_tag()
    if tag.startswith("manylinux2014_"):
        return tag.replace("manylinux2014_", "musllinux_1_2_")
    if tag.startswith("musllinux_1_2_"):
        return tag.replace("musllinux_1_2_", "manylinux2014_")
    return None


def engine_repo(generation=3):
    _engine(generation)
    return ENGINE_REPO


def engine_version(generation=3):
    _engine(generation)
    return ENGINE_VERSION


def repo_prefix(generation=3):
    _engine(generation)
    return f"releases/{ENGINE_VERSION}/"


def engine_wheel(version, tag, generation=3):
    _engine(generation)
    return f"releases/{version}/python/cactus_runtime-{version}-py3-none-{tag}.whl"


def _cache_root():
    return os.path.join(os.environ.get("XDG_CACHE_HOME", os.path.expanduser("~/.cache")), "cactus")


def engine_cache_dir():
    return os.path.join(_cache_root(), "engine", ENGINE_VERSION, ENGINE_REVISION)


def cache_dir(generation=3):
    key = _engine(generation)
    return os.path.join(_cache_root(), "models", BASE_WEIGHTS[key][:-5], MODEL_REVISIONS[key])


def base_weights(generation=3):
    return BASE_WEIGHTS[_engine(generation)]


def _sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def _atomic_write(path, data):
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=".cactus-", dir=os.path.dirname(os.path.abspath(path)))
    try:
        with os.fdopen(fd, "wb") as target:
            target.write(data)
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return path


def _manifest():
    from huggingface_hub import hf_hub_download
    if len(ENGINE_REVISION) != 40 or len(MANIFEST_SHA256) != 64:
        raise RuntimeError("this Cactus client has no verified engine release pin")
    path = hf_hub_download(repo_id=ENGINE_REPO, filename=repo_prefix() + "manifest.json", revision=ENGINE_REVISION)
    if _sha256(path) != MANIFEST_SHA256:
        raise RuntimeError("engine release manifest checksum mismatch")
    with open(path) as source:
        manifest = json.load(source)
    if manifest.get("version") != ENGINE_VERSION or manifest.get("api") != "cactus":
        raise RuntimeError("incompatible engine release manifest")
    return manifest


def _artifact(filename):
    from huggingface_hub import hf_hub_download
    manifest = _manifest()
    entry = manifest["files"][filename]
    path = hf_hub_download(repo_id=ENGINE_REPO, filename=repo_prefix() + filename, revision=ENGINE_REVISION)
    if os.path.getsize(path) != entry["size"] or _sha256(path) != entry["sha256"]:
        raise RuntimeError(f"engine artifact checksum mismatch: {filename}")
    return path


def unpublished_engine_wheels():
    """Validate every pinned runtime wheel's remote checksum before a client release."""
    from huggingface_hub import HfApi
    manifest = _manifest()
    paths = [engine_wheel(ENGINE_VERSION, tag) for tag in WHEEL_TAGS]
    entries = {entry.path: entry for entry in HfApi().get_paths_info(ENGINE_REPO, paths, revision=ENGINE_REVISION)}
    missing = []
    for path in paths:
        entry = entries.get(path)
        expected = manifest["files"].get(path[len(repo_prefix()):])
        if not entry or not expected or entry.size != expected["size"]:
            missing.append(ENGINE_REPO + "/" + path)
            continue
        if entry.lfs:
            valid = entry.lfs.sha256 == expected["sha256"]
        else:
            try:
                _artifact(path[len(repo_prefix()):])
                valid = True
            except RuntimeError:
                valid = False
        if not valid:
            missing.append(ENGINE_REPO + "/" + path)
    return missing


def _register_download(generation=3):
    from huggingface_hub import hf_hub_download
    key = _engine(generation)
    try:
        hf_hub_download(repo_id=MODEL_REPOS[key], filename="config.json", revision=MODEL_REVISIONS[key], force_download=True)
    except Exception:
        pass


def download_platform(name, out_dir, generation=3, dest=None):
    _engine(generation)
    if name not in PLATFORMS:
        raise ValueError(f"unsupported platform: {name}")
    manifest = _manifest()
    files = [path for path in manifest["files"] if path.startswith(name + "/")]
    if not files:
        raise FileNotFoundError(f"{name} is missing from the pinned engine release")
    dest = dest or os.path.join(out_dir, name)
    outputs = []
    for filename in files:
        cached = _artifact(filename)
        target = os.path.join(dest, os.path.basename(filename))
        with open(cached, "rb") as source:
            _atomic_write(target, source.read())
        if os.path.basename(target) in ("cactus", "cactus.exe"):
            os.chmod(target, os.stat(target).st_mode | 0o111)
        outputs.append(target)
    return outputs


def fetch_weights(generation=3, dest_dir=None, force=False):
    from huggingface_hub import hf_hub_download
    key = _engine(generation)
    override = os.environ.get("CACTUS_" + ("NEEDLE" if key == 3 else key.upper()) + "_WEIGHTS")
    if override:
        return os.fspath(override)
    _register_download(key)
    name = base_weights(key)
    dest_dir = dest_dir or cache_dir(key)
    out = os.path.join(dest_dir, name)
    expected = MODEL_SHA256.get(key)
    if os.path.exists(out) and not force and expected and _sha256(out) == expected:
        return out
    cached = hf_hub_download(repo_id=MODEL_REPOS[key], filename=name, revision=MODEL_REVISIONS[key], force_download=force)
    if expected and _sha256(cached) != expected:
        raise RuntimeError(f"model checksum mismatch: {name}")
    with open(cached, "rb") as source:
        return _atomic_write(out, source.read())


def fetch_checkpoint(name, dest_dir, generation=3, force=False):
    from huggingface_hub import hf_hub_download
    from huggingface_hub.errors import EntryNotFoundError
    key = _engine(generation)
    _register_download(key)
    base = os.path.basename(name)
    for candidate in (f"{CHECKPOINT_PREFIX}/{base}", base):
        try:
            cached = hf_hub_download(repo_id=MODEL_REPOS[key], filename=candidate, revision=MODEL_REVISIONS[key], force_download=force)
            with open(cached, "rb") as source:
                return _atomic_write(os.path.join(dest_dir, base), source.read())
        except EntryNotFoundError:
            continue
    raise FileNotFoundError(f"{base} is not published in {MODEL_REPOS[key]}")


def fetch_library(version=None, dest_dir=None, tag=None, generation=3):
    _engine(generation)
    if version is not None and version != ENGINE_VERSION:
        raise ValueError("only the pinned engine version can be downloaded")
    tag = tag or _platform_tag()
    if tag not in WHEEL_TAGS:
        raise ValueError(f"unsupported wheel tag: {tag}")
    path = _artifact(f"python/cactus_runtime-{ENGINE_VERSION}-py3-none-{tag}.whl")
    member = "cactus/" + lib_name(tag=tag)
    with zipfile.ZipFile(path) as archive:
        data = archive.read(member)
    out = os.path.join(dest_dir or engine_cache_dir(), lib_name(tag=tag))
    if not os.path.isfile(out) or _sha256(out) != hashlib.sha256(data).hexdigest():
        _atomic_write(out, data)
    return out
from __future__ import annotations

import enum
import inspect
import re
import types
import typing
from typing import Callable

_JSON_TYPES = {str: "string", int: "integer", float: "number", bool: "boolean",
               list: "array", dict: "object"}


_UNION_ORIGINS = (typing.Union, getattr(types, "UnionType", typing.Union))

_MISSING = object()


class Field:
    def __init__(self, default=_MISSING, *, description=None, enum=None, const=_MISSING,
                 ge=None, le=None, gt=None, lt=None, multiple_of=None,
                 min_length=None, max_length=None, pattern=None, format=None,
                 min_items=None, max_items=None, unique_items=None):
        self.default = default
        self.description = description
        self.enum = enum
        self.const = const
        self.ge, self.le, self.gt, self.lt = ge, le, gt, lt
        self.multiple_of = multiple_of
        self.min_length, self.max_length = min_length, max_length
        self.pattern, self.format = pattern, format
        self.min_items, self.max_items, self.unique_items = min_items, max_items, unique_items

    def has_default(self):
        return self.default is not _MISSING

    def apply(self, schema):
        pairs = (("description", self.description), ("enum", self.enum),
                 ("minimum", self.ge), ("maximum", self.le),
                 ("exclusiveMinimum", self.gt), ("exclusiveMaximum", self.lt),
                 ("multipleOf", self.multiple_of), ("minLength", self.min_length),
                 ("maxLength", self.max_length), ("pattern", self.pattern),
                 ("format", self.format), ("minItems", self.min_items),
                 ("maxItems", self.max_items), ("uniqueItems", self.unique_items))
        for key, value in pairs:
            if value is not None:
                schema[key] = list(value) if key == "enum" else value
        if self.const is not _MISSING:
            schema["const"] = self.const
        return schema


def _is_optional(annotation):
    if typing.get_origin(annotation) is typing.Annotated:
        return _is_optional(typing.get_args(annotation)[0])
    return (typing.get_origin(annotation) in _UNION_ORIGINS
            and type(None) in typing.get_args(annotation))


def _json_type(annotation, defs):
    if annotation is inspect.Parameter.empty or annotation is None:
        return {"type": "string"}
    origin = typing.get_origin(annotation)
    if origin is typing.Annotated:
        return _json_type(typing.get_args(annotation)[0], defs)
    if origin is None:
        if annotation in _JSON_TYPES:
            return {"type": _JSON_TYPES[annotation]}
        if isinstance(annotation, type) and issubclass(annotation, enum.Enum):
            values = [e.value for e in annotation]
            val_type = _JSON_TYPES.get(type(values[0]), "string") if values else "string"
            return {"type": val_type, "enum": values}
        if _is_pydantic_model(annotation):
            schema = pydantic_schema(annotation)["parameters"]
            for key in ("$defs", "definitions"):
                if key in schema:
                    defs.setdefault(key, {}).update(schema.pop(key))
            return schema
        return {"type": "string"}
    if origin is typing.Literal:
        args = list(typing.get_args(annotation))
        val_type = _JSON_TYPES.get(type(args[0]), "string") if args else "string"
        return {"type": val_type, "enum": args}
    if origin in (list, typing.List):
        args = typing.get_args(annotation)
        return {"type": "array", "items": _json_type(args[0], defs) if args else {"type": "string"}}
    if origin in (dict, typing.Dict):
        return {"type": "object"}
    if origin in _UNION_ORIGINS:
        rest = [a for a in typing.get_args(annotation) if a is not type(None)]
        if rest:
            return _json_type(rest[0], defs)
    return {"type": "string"}


def _field_of(annotation, default):
    if isinstance(default, Field):
        return default
    origin = typing.get_origin(annotation)
    if origin is typing.Annotated:
        for meta in typing.get_args(annotation)[1:]:
            if isinstance(meta, Field):
                return meta
    if origin in _UNION_ORIGINS:
        rest = [a for a in typing.get_args(annotation) if a is not type(None)]
        if len(rest) == 1:
            return _field_of(rest[0], _MISSING)
    return None


def _parse_doc(doc):
    if not doc:
        return "", {}
    lines = doc.strip("\n").splitlines()
    heads = ("args:", "arguments:", "parameters:", "params:")
    desc, args, i = [], {}, 0
    while i < len(lines) and lines[i].strip().lower() not in heads:
        desc.append(lines[i].strip())
        i += 1
    head = _indent(lines[i]) if i < len(lines) else 0
    name, depth = None, 0
    for line in lines[i + 1:]:
        if not line.strip():
            continue

        if _indent(line) <= head and re.match(r"\s*[A-Za-z][\w ]*:\s*$", line):
            break
        m = re.match(r"\s+(\w+)\s*(?:\([^)]*\))?\s*:\s*(.+)", line)
        if m and (name is None or _indent(line) <= depth):
            name, depth = m.group(1), _indent(line)
            args[name] = m.group(2).strip()
        elif name and _indent(line) > depth:


            args[name] += " " + line.strip()
    return " ".join(w for w in desc if w).strip(), args


def _indent(line):
    return len(line) - len(line.lstrip())


def build_schema(fn: Callable) -> dict:
    signature = inspect.signature(fn)
    try:
        hints = typing.get_type_hints(fn, include_extras=True)
    except Exception:
        hints = {}
    description, arg_docs = _parse_doc(fn.__doc__)
    properties, required, defs = {}, [], {}

